1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	/** File descriptor 0 is stdin; reading it whole is what makes this a pipe filter. */
5	const STDIN = 0;
6	
7	/**
8	 * The sentence the customer sees on stderr when the MHPCO refuses something.
9	 *
10	 * Every rejection is an `Error` thrown by the library, so the `instanceof` arm
11	 * is the real path and `String(cause)` only covers a non-`Error` throw that no
12	 * code here produces. It stays because the alternative — asserting the type —
13	 * would print "undefined" for that case instead of something a reader can act
14	 * on, and this text is the only diagnostic a piped caller gets.
15	 */
16	const rejectionMessage = (cause: unknown): string =>
17	  cause instanceof Error ? cause.message : String(cause);
18	
19	// A scenario in, its results out: the CLI's whole job is to move JSON across
20	// the process boundary, so every decision about what those results ARE lives in
21	// claim-office.ts and none of it is repeated here.
22	try {
23	  const scenario = JSON.parse(readFileSync(STDIN, "utf8")) as Scenario;
24	  process.stdout.write(JSON.stringify({ results: runScenario(scenario) }));
25	} catch (error) {
26	  // The library states a refusal by throwing; turning that into an exit code the
27	  // caller can branch on is the part only the CLI can do. Malformed JSON lands
28	  // here too, and is reported the same way — from the caller's side both are
29	  // "the MHPCO would not process this input".
30	  process.stderr.write(`${rejectionMessage(error)}\n`);
31	  process.exit(1);
32	}
